45	fheroes2::Image GetNonStandardSizeIcon( void )
46	{
47	    fheroes2::Image icon( 17, 17 );
48	    icon.reset();
49	    fheroes2::Fill( icon, 1, 1, 15, 15, fheroes2::GetColorId( 0x8D, 0x73, 0xFF ) );
50	    Text text( "N", Font::SMALL );
51	    text.Blit( ( 17 - text.w() ) / 2, ( 17 - text.h() ) / 2, icon );
52	    return icon;
53	}
