55	void ScenarioListBox::RedrawItem( const Maps::FileInfo & info, s32 dstx, s32 dsty, bool current )
56	{
57	    fheroes2::Display & display = fheroes2::Display::instance();
58	
59	    int index = 19 + Color::Count( info.kingdom_colors );
60	
61	    dstx = dstx - 10;
62	    dsty = dsty + 2;
63	
64	    int32_t offsetX = 0;
65	
66	    const fheroes2::Sprite & spriteCount = fheroes2::AGG::GetICN( ICN::REQUESTS, index );
67	    fheroes2::Blit( spriteCount, display, dstx, dsty );
68	
69	    offsetX += spriteCount.width() + 2;
70	
71	    if ( info.size_w != info.size_h || info.size_w < Maps::SMALL || info.size_w > Maps::XLARGE ) {
72	        const fheroes2::Image & nonStandardIcon = GetNonStandardSizeIcon();
73	
74	        fheroes2::Blit( nonStandardIcon, display, dstx + offsetX, dsty );
75	        offsetX += nonStandardIcon.width() + 2;
76	    }
77	    else {
78	        switch ( info.size_w ) {
79	        case Maps::SMALL:
80	            index = 26;
81	            break;
82	        case Maps::MEDIUM:
83	            index = 27;
84	            break;
85	        case Maps::LARGE:
86	            index = 28;
87	            break;
88	        case Maps::XLARGE:
89	            index = 29;
90	            break;
91	        default:
92	            break;
93	        }
94	
95	        const fheroes2::Sprite & spriteSize = fheroes2::AGG::GetICN( ICN::REQUESTS, index );
96	        fheroes2::Blit( spriteSize, display, dstx + offsetX, dsty );
97	        offsetX += spriteSize.width() + 2;
98	    }
99	
100	    const fheroes2::Sprite & mapType = fheroes2::AGG::GetICN( ICN::MAP_TYPE_ICON, info._version == GameVersion::PRICE_OF_LOYALTY ? 1 : 0 );
101	    fheroes2::Blit( mapType, display, dstx + offsetX, dsty );
102	
103	    fheroes2::Text mapName( info.name, { fheroes2::FontSize::NORMAL, ( current ? fheroes2::FontColor::YELLOW : fheroes2::FontColor::WHITE ) } );
104	    mapName.draw( dstx + 58, dsty + ( mapType.height() - mapName.height() ) / 2 + 2, display );
105	
106	    index = 30 + info.conditions_wins;
107	    const fheroes2::Sprite & spriteWins = fheroes2::AGG::GetICN( ICN::REQUESTS, index );
108	    fheroes2::Blit( spriteWins, display, dstx + 224, dsty );
109	
110	    index = 36 + info.conditions_loss;
111	    const fheroes2::Sprite & spriteLoss = fheroes2::AGG::GetICN( ICN::REQUESTS, index );
112	    fheroes2::Blit( spriteLoss, display, dstx + 224 + spriteWins.width() + 2, dsty );
113	}
