120	void ScenarioListBox::ActionListPressRight( Maps::FileInfo & info )
121	{
122	    // On some OSes like Windows, the path may contain '\' symbols. This symbol doesn't exist in the resources.
123	    // To avoid this we have to replace all '\' symbols by '/' symbols.
124	    std::string fullPath = info.file;
125	    StringReplace( fullPath, "\\", "/" );
126	
127	    fheroes2::Text header( info.name, { fheroes2::FontSize::NORMAL, fheroes2::FontColor::YELLOW } );
128	
129	    fheroes2::MultiFontText body;
130	    body.add( { _( "Location: " ), { fheroes2::FontSize::NORMAL, fheroes2::FontColor::YELLOW } } );
131	    body.add( { fullPath, { fheroes2::FontSize::NORMAL, fheroes2::FontColor::WHITE } } );
132	    body.add( { _( "\n\nMap Type:\n" ), { fheroes2::FontSize::NORMAL, fheroes2::FontColor::YELLOW } } );
133	    switch ( info._version ) {
134	    case GameVersion::SUCCESSION_WARS:
135	        body.add( { _( "The Succession Wars" ), { fheroes2::FontSize::NORMAL, fheroes2::FontColor::WHITE } } );
136	        break;
137	    case GameVersion::PRICE_OF_LOYALTY:
138	        body.add( { _( "The Price of Loyalty" ), { fheroes2::FontSize::NORMAL, fheroes2::FontColor::WHITE } } );
139	        break;
140	    default:
141	        // Did you add a new map version? Add the logic above!
142	        assert( 0 );
143	        break;
144	    }
145	
146	    fheroes2::showMessage( header, body, Dialog::ZERO );
147	}
