149	void ScenarioListBox::RedrawBackground( const fheroes2::Point & dst )
150	{
151	    fheroes2::Display & display = fheroes2::Display::instance();
152	    fheroes2::Blit( fheroes2::AGG::GetICN( ICN::REQSBKG, 0 ), display, dst.x, dst.y );
153	
154	    if ( isSelected() ) {
155	        Text text;
156	        const Maps::FileInfo & info = GetCurrent();
157	        int index = 19 + Color::Count( info.kingdom_colors );
158	
159	        const fheroes2::Sprite & spriteCount = fheroes2::AGG::GetICN( ICN::REQUESTS, index );
160	        fheroes2::Blit( spriteCount, display, dst.x + 46, dst.y + 265 );
161	
162	        switch ( info.size_w ) {
163	        case Maps::SMALL:
164	            index = 26;
165	            break;
166	        case Maps::MEDIUM:
167	            index = 27;
168	            break;
169	        case Maps::LARGE:
170	            index = 28;
171	            break;
172	        case Maps::XLARGE:
173	            index = 29;
174	            break;
175	        default:
176	            index = 30;
177	            break;
178	        }
179	
180	        const fheroes2::Sprite & spriteSize = fheroes2::AGG::GetICN( ICN::REQUESTS, index );
181	        fheroes2::Blit( spriteSize, display, dst.x + 46 + spriteCount.width() + 2, dst.y + 265 );
182	
183	        const fheroes2::Sprite & mapType = fheroes2::AGG::GetICN( ICN::MAP_TYPE_ICON, info._version == GameVersion::PRICE_OF_LOYALTY ? 1 : 0 );
184	        fheroes2::Blit( mapType, display, dst.x + 46 + spriteCount.width() + 2 * 2 + spriteSize.width(), dst.y + 265 );
185	
186	        text.Set( info.name, Font::BIG );
187	        text.Blit( dst.x + 190 - text.w() / 2, dst.y + 265 );
188	
189	        index = 30 + info.conditions_wins;
190	        const fheroes2::Sprite & spriteWins = fheroes2::AGG::GetICN( ICN::REQUESTS, index );
191	        fheroes2::Blit( spriteWins, display, dst.x + 275, dst.y + 265 );
192	
193	        index = 36 + info.conditions_loss;
194	        const fheroes2::Sprite & spriteLoss = fheroes2::AGG::GetICN( ICN::REQUESTS, index );
195	        fheroes2::Blit( spriteLoss, display, dst.x + 275 + spriteWins.width() + 2, dst.y + 265 );
196	
197	        text.Set( _( "Map difficulty:" ), Font::BIG );
198	        text.Blit( dst.x + 180 - text.w(), dst.y + 290 );
199	
200	        text.Set( Difficulty::String( info.difficulty ) );
201	        text.Blit( dst.x + 275 - text.w() / 2, dst.y + 290 );
202	
203	        TextBox box( info.description, Font::BIG, 290 );
204	        box.Blit( dst.x + 45, dst.y + 320 );
205	    }
206	}
