208	const Maps::FileInfo * Dialog::SelectScenario( const MapsFileInfoList & all, size_t selectedId )
209	{
210	    if ( all.empty() )
211	        return nullptr;
212	
213	    if ( selectedId >= all.size() )
214	        selectedId = 0;
215	
216	    fheroes2::Display & display = fheroes2::Display::instance();
217	    LocalEvent & le = LocalEvent::Get();
218	
219	    // setup cursor
220	    const CursorRestorer cursorRestorer( true, Cursor::POINTER );
221	
222	    const Maps::FileInfo * result = nullptr;
223	    MapsFileInfoList small;
224	    MapsFileInfoList medium;
225	    MapsFileInfoList large;
226	    MapsFileInfoList xlarge;
227	
228	    small.reserve( all.size() );
229	    medium.reserve( all.size() );
230	    large.reserve( all.size() );
231	    xlarge.reserve( all.size() );
232	
233	    for ( MapsFileInfoList::const_iterator cur = all.begin(); cur != all.end(); ++cur ) {
234	        switch ( ( *cur ).size_w ) {
235	        case Maps::SMALL:
236	            small.push_back( *cur );
237	            break;
238	        case Maps::MEDIUM:
239	            medium.push_back( *cur );
240	            break;
241	        case Maps::LARGE:
242	            large.push_back( *cur );
243	            break;
244	        case Maps::XLARGE:
245	            xlarge.push_back( *cur );
246	            break;
247	        default:
248	            continue;
249	        }
250	    }
251	
252	    const fheroes2::Sprite & panel = fheroes2::AGG::GetICN( ICN::REQSBKG, 0 );
253	    fheroes2::Rect rt( ( display.width() - panel.width() ) / 2, ( display.height() - panel.height() ) / 2, panel.width(), panel.height() );
254	
255	    fheroes2::ImageRestorer background( display, rt.x - SHADOWWIDTH, rt.y, rt.width + SHADOWWIDTH, rt.height + SHADOWWIDTH );
256	
257	    const fheroes2::Sprite & shadow = fheroes2::AGG::GetICN( ICN::REQSBKG, 1 );
258	    fheroes2::Blit( shadow, display, rt.x - SHADOWWIDTH, rt.y + SHADOWWIDTH );
259	
260	    const fheroes2::Rect countPlayers( rt.x + 45, rt.y + 55, 19, 175 );
261	    const fheroes2::Rect sizeMaps( rt.x + 64, rt.y + 55, 19, 175 );
262	    const fheroes2::Rect mapType( rt.x + 83, rt.y + 55, 19, 175 );
263	    const fheroes2::Rect victoryConds( rt.x + 268, rt.y + 55, 19, 175 );
264	    const fheroes2::Rect lossConds( rt.x + 287, rt.y + 55, 19, 175 );
265	
266	    const fheroes2::Rect curCountPlayer( rt.x + 46, rt.y + 264, 18, 18 );
267	    const fheroes2::Rect curMapSize( rt.x + 65, rt.y + 264, 18, 18 );
268	    const fheroes2::Rect curMapType( rt.x + 84, rt.y + 264, 19, 18 );
269	    const fheroes2::Rect curMapName( rt.x + 107, rt.y + 264, 166, 18 );
270	    const fheroes2::Rect curVictoryCond( rt.x + 274, rt.y + 264, 19, 18 );
271	    const fheroes2::Rect curLossCond( rt.x + 293, rt.y + 264, 19, 18 );
272	    const fheroes2::Rect curDifficulty( rt.x + 220, rt.y + 292, 114, 20 );
273	    const fheroes2::Rect curDescription( rt.x + 42, rt.y + 316, 292, 90 );
274	
275	    fheroes2::Button buttonOk( rt.x + 140, rt.y + 410, ICN::REQUESTS, 1, 2 );
276	
277	    fheroes2::Button buttonSelectSmall( rt.x + 37, rt.y + 22, ICN::REQUESTS, 9, 10 );
278	    fheroes2::Button buttonSelectMedium( rt.x + 99, rt.y + 22, ICN::REQUESTS, 11, 12 );
279	    fheroes2::Button buttonSelectLarge( rt.x + 161, rt.y + 22, ICN::REQUESTS, 13, 14 );
280	    fheroes2::Button buttonSelectXLarge( rt.x + 223, rt.y + 22, ICN::REQUESTS, 15, 16 );
281	    fheroes2::Button buttonSelectAll( rt.x + 285, rt.y + 22, ICN::REQUESTS, 17, 18 );
282	
283	    buttonSelectAll.press();
284	    fheroes2::ButtonBase * currentPressedButton = &buttonSelectAll;
285	
286	    fheroes2::OptionButtonGroup buttonGroup;
287	    buttonGroup.addButton( &buttonSelectSmall );
288	    buttonGroup.addButton( &buttonSelectMedium );
289	    buttonGroup.addButton( &buttonSelectLarge );
290	    buttonGroup.addButton( &buttonSelectXLarge );
291	    buttonGroup.addButton( &buttonSelectAll );
292	
293	    ScenarioListBox listbox( rt.getPosition() );
294	
295	    listbox.RedrawBackground( rt.getPosition() );
296	    listbox.SetScrollButtonUp( ICN::REQUESTS, 5, 6, fheroes2::Point( rt.x + 327, rt.y + 55 ) );
297	    listbox.SetScrollButtonDn( ICN::REQUESTS, 7, 8, fheroes2::Point( rt.x + 327, rt.y + 217 ) );
298	
299	    listbox.SetScrollBar( fheroes2::AGG::GetICN( ICN::ESCROLL, 3 ), fheroes2::Rect( rt.x + 328, rt.y + 73, 12, 140 ) );
300	    listbox.SetAreaMaxItems( 9 );
301	    listbox.SetAreaItems( fheroes2::Rect( rt.x + 55, rt.y + 55, 270, 175 ) );
302	    listbox.SetListContent( const_cast<MapsFileInfoList &>( all ) );
303	    listbox.SetCurrent( selectedId );
304	    listbox.Redraw();
305	
306	    buttonOk.draw();
307	    buttonSelectSmall.draw();
308	    buttonSelectMedium.draw();
309	    buttonSelectLarge.draw();
310	    buttonSelectXLarge.draw();
311	    buttonSelectAll.draw();
312	
313	    display.render();
314	
315	    while ( le.HandleEvents() ) {
316	        if ( buttonOk.isEnabled() )
317	            le.MousePressLeft( buttonOk.area() ) ? buttonOk.drawOnPress() : buttonOk.drawOnRelease();
318	
319	        if ( le.MousePressLeft( buttonSelectSmall.area() ) )
320	            buttonSelectSmall.drawOnPress();
321	        if ( le.MousePressLeft( buttonSelectMedium.area() ) )
322	            buttonSelectMedium.drawOnPress();
323	        if ( le.MousePressLeft( buttonSelectLarge.area() ) )
324	            buttonSelectLarge.drawOnPress();
325	        if ( le.MousePressLeft( buttonSelectXLarge.area() ) )
326	            buttonSelectXLarge.drawOnPress();
327	        if ( le.MousePressLeft( buttonSelectAll.area() ) )
328	            buttonSelectAll.drawOnPress();
329	
330	        listbox.QueueEventProcessing();
331	
332	        bool needRedraw = false;
333	
334	        if ( ( buttonOk.isEnabled() && le.MouseClickLeft( buttonOk.area() ) ) || Game::HotKeyPressEvent( Game::EVENT_DEFAULT_READY ) || listbox.selectOk ) {
335	            MapsFileInfoList::const_iterator it = std::find( all.begin(), all.end(), listbox.GetCurrent() );
336	            result = it != all.end() ? &( *it ) : nullptr;
337	            break;
338	        }
339	        else if ( Game::HotKeyPressEvent( Game::EVENT_DEFAULT_EXIT ) ) {
340	            result = nullptr;
341	            break;
342	        }
343	        else if ( le.MouseClickLeft( buttonSelectSmall.area() ) || le.KeyPress( KEY_s ) /*&& buttonSelectSmall.isEnabled()*/ ) {
344	            if ( small.empty() ) {
345	                Dialog::Message( "", _( "No maps exist at that size" ), Font::BIG, Dialog::OK );
346	                currentPressedButton->drawOnPress();
347	            }
348	            else {
349	                listbox.SetListContent( small );
350	                currentPressedButton = &buttonSelectSmall;
351	                currentPressedButton->press();
352	            }
353	
354	            needRedraw = true;
355	        }
356	        else if ( le.MouseClickLeft( buttonSelectMedium.area() ) || le.KeyPress( KEY_m ) /*&& buttonSelectMedium.isEnabled()*/ ) {
357	            if ( medium.empty() ) {
358	                Dialog::Message( "", _( "No maps exist at that size" ), Font::BIG, Dialog::OK );
359	                currentPressedButton->drawOnPress();
360	            }
361	            else {
362	                listbox.SetListContent( medium );
363	                currentPressedButton = &buttonSelectMedium;
364	                currentPressedButton->press();
365	            }
366	
367	            needRedraw = true;
368	        }
369	        else if ( le.MouseClickLeft( buttonSelectLarge.area() ) || le.KeyPress( KEY_l ) /*&& buttonSelectLarge.isEnabled()*/ ) {
370	            if ( large.empty() ) {
371	                Dialog::Message( "", _( "No maps exist at that size" ), Font::BIG, Dialog::OK );
372	                currentPressedButton->drawOnPress();
373	            }
374	            else {
375	                listbox.SetListContent( large );
376	                currentPressedButton = &buttonSelectLarge;
377	                currentPressedButton->press();
378	            }
379	
380	            needRedraw = true;
381	        }
382	        else if ( le.MouseClickLeft( buttonSelectXLarge.area() ) || le.KeyPress( KEY_x ) /*&& buttonSelectXLarge.isEnabled()*/ ) {
383	            if ( xlarge.empty() ) {
384	                Dialog::Message( "", _( "No maps exist at that size" ), Font::BIG, Dialog::OK );
385	                currentPressedButton->drawOnPress();
386	            }
387	            else {
388	                listbox.SetListContent( xlarge );
389	                currentPressedButton = &buttonSelectXLarge;
390	                currentPressedButton->press();
391	            }
392	
393	            needRedraw = true;
394	        }
395	        else if ( le.MouseClickLeft( buttonSelectAll.area() ) || le.KeyPress( KEY_a ) ) {
396	            listbox.SetListContent( const_cast<MapsFileInfoList &>( all ) );
397	            currentPressedButton = &buttonSelectAll;
398	            currentPressedButton->press();
399	
400	            needRedraw = true;
401	        }
402	
403	        // right info
404	        if ( le.MousePressRight( buttonSelectSmall.area() ) )
405	            Dialog::Message( _( "Small Maps" ), _( "View only maps of size small (36 x 36)." ), Font::BIG );
406	        else if ( le.MousePressRight( buttonSelectMedium.area() ) )
407	            Dialog::Message( _( "Medium Maps" ), _( "View only maps of size medium (72 x 72)." ), Font::BIG );
408	        else if ( le.MousePressRight( buttonSelectLarge.area() ) )
409	            Dialog::Message( _( "Large Maps" ), _( "View only maps of size large (108 x 108)." ), Font::BIG );
410	        else if ( le.MousePressRight( buttonSelectXLarge.area() ) )
411	            Dialog::Message( _( "Extra Large Maps" ), _( "View only maps of size extra large (144 x 144)." ), Font::BIG );
412	        else if ( le.MousePressRight( buttonSelectAll.area() ) )
413	            Dialog::Message( _( "All Maps" ), _( "View all maps, regardless of size." ), Font::BIG );
414	        else if ( le.MousePressRight( countPlayers ) || le.MousePressRight( curCountPlayer ) )
415	            Dialog::Message( _( "Players Icon" ),
416	                             _( "Indicates how many players total are in the scenario. Any positions not occupied by humans will be occupied by computer players." ),
417	                             Font::BIG );
418	        else if ( le.MousePressRight( sizeMaps ) || le.MousePressRight( curMapSize ) )
419	            Dialog::Message( _( "Size Icon" ), _( "Indicates whether the map\nis small (36 x 36), medium\n(72 x 72), large (108 x 108),\nor extra large (144 x 144)." ),
420	                             Font::BIG );
421	        else if ( le.MousePressRight( curMapName ) )
422	            Dialog::Message( _( "Selected Name" ), _( "The name of the currently selected map." ), Font::BIG );
423	        else if ( le.MousePressRight( mapType ) || le.MousePressRight( curMapType ) )
424	            Dialog::Message( _( "Map Type" ), _( "Indicates whether the map is made for The Succession Wars or The Price of Loyalty version of the game." ), Font::BIG );
425	        else if ( le.MousePressRight( victoryConds ) ) {
426	            const Maps::FileInfo * item = listbox.GetFromPosition( le.GetMouseCursor() );
427	            if ( item )
428	                VictoryConditionInfo( *item );
429	        }
430	        else if ( le.MousePressRight( lossConds ) ) {
431	            const Maps::FileInfo * item = listbox.GetFromPosition( le.GetMouseCursor() );
432	            if ( item )
433	                LossConditionInfo( *item );
434	        }
435	        else if ( le.MousePressRight( curVictoryCond ) )
436	            VictoryConditionInfo( listbox.GetCurrent() );
437	        else if ( le.MousePressRight( curLossCond ) )
438	            LossConditionInfo( listbox.GetCurrent() );
439	        else if ( le.MousePressRight( curDifficulty ) )
440	            Dialog::Message(
441	                _( "Selected Map Difficulty" ),
442	                _( "The map difficulty of the currently selected map.  The map difficulty is determined by the scenario designer. More difficult maps might include more or stronger enemies, fewer resources, or other special conditions making things tougher for the human player." ),
443	                Font::BIG );
444	        else if ( le.MousePressRight( curDescription ) )
445	            Dialog::Message( _( "Selected Description" ), _( "The description of the currently selected map." ), Font::BIG );
446	        else if ( le.MousePressRight( buttonOk.area() ) )
447	            Dialog::Message( _( "Okay" ), _( "Accept the choice made." ), Font::BIG );
448	
449	        if ( !needRedraw && !listbox.IsNeedRedraw() ) {
450	            continue;
451	        }
452	
453	        listbox.Redraw();
454	        buttonOk.draw();
455	        buttonSelectSmall.draw();
456	        buttonSelectMedium.draw();
457	        buttonSelectLarge.draw();
458	        buttonSelectXLarge.draw();
459	        buttonSelectAll.draw();
460	        display.render();
461	    }
462	
463	    return result;
464	}
465	
466	void LossConditionInfo( const Maps::FileInfo & info )
467	{
468	    std::string msg;
469	
470	    switch ( info.conditions_loss ) {
471	    case 0:
472	        msg = _( "Lose all your heroes and towns." );
473	        break;
474	    case 1:
475	        msg = _( "Lose a specific town." );
476	        break;
477	    case 2:
478	        msg = _( "Lose a specific hero." );
479	        break;
480	    case 3:
481	        msg = _( "Run out of time. Fail to win by a certain point." );
482	        break;
483	    default:
484	        return;
485	    }
486	    Dialog::Message( _( "Loss Condition" ), msg, Font::BIG );
487	}
488	
489	void VictoryConditionInfo( const Maps::FileInfo & info )
490	{
491	    std::string msg;
492	
493	    switch ( info.conditions_wins ) {
494	    case 0:
495	        msg = _( "Defeat all enemy heroes and towns." );
496	        break;
497	    case 1:
498	        msg = _( "Capture a specific town." );
499	        break;
500	    case 2:
501	        msg = _( "Defeat a specific hero." );
502	        break;
503	    case 3:
504	        msg = _( "Find a specific artifact." );
505	        break;
506	    case 4:
507	        msg = _( "Your side defeats the opposing side." );
508	        break;
509	    case 5:
510	        msg = _( "Accumulate a large amount of gold." );
511	        break;
512	    default:
513	        return;
514	    }
515	    Dialog::Message( _( "Victory Condition" ), msg, Font::BIG );
516	}
