148	        void SetListContent( std::vector<Item> & list )
149	        {
150	            content = &list;
151	            Reset();
152	
153	            if ( IsValid() )
154	                _currentId = 0;
155	        }
156	
157	        void Reset()
158	        {
159	            if ( content == nullptr || content->empty() ) { // empty content. Must be non-initialized array
160	                _currentId = -1;
161	                _topId = -1;
162	                _scrollbar.setRange( 0, 0 );
163	            }
164	            else {
165	                _currentId = -1; // no selection
166	                _topId = 0;
167	
168	                if ( maxItems < _size() ) {
169	                    _scrollbar.setRange( 0, _size() - maxItems );
170	                }
171	                else {
172	                    _scrollbar.setRange( 0, 0 );
173	                }
174	            }
175	        }
