182	        void Redraw() override
183	        {
184	            needRedraw = false;
185	
186	            RedrawBackground( ptRedraw );
187	
188	            buttonPgUp.draw();
189	            buttonPgDn.draw();
190	            _scrollbar.redraw();
191	
192	            Verify(); // reset values if they are wrong
193	
194	            if ( IsValid() ) { // we have something to display
195	                int id = _topId;
196	                const int end = ( _topId + maxItems ) > _size() ? _size() - _topId : _topId + maxItems;
197	                for ( ; id < end; ++id )
198	                    RedrawItem( ( *content )[id], rtAreaItems.x, rtAreaItems.y + ( id - _topId ) * rtAreaItems.height / maxItems, id == _currentId );
199	            }
200	        }
