217	        Item * GetFromPosition( const fheroes2::Point & mp )
218	        {
219	            Verify();
220	            if ( !IsValid() )
221	                return nullptr;
222	
223	            if ( mp.y < rtAreaItems.y || mp.y >= rtAreaItems.y + rtAreaItems.height ) // out of boundaries
224	                return nullptr;
225	
226	            if ( mp.x < rtAreaItems.x || mp.x >= rtAreaItems.x + rtAreaItems.width ) // out of boundaries
227	                return nullptr;
228	
229	            const int id = ( mp.y - rtAreaItems.y ) * maxItems / rtAreaItems.height;
230	            if ( _topId + id >= _size() ) // out of items
231	                return nullptr;
