244	        void SetCurrentVisible( void )
245	        {
246	            Verify();
247	
248	            if ( !IsValid() ) {
249	                Reset();
250	                return;
251	            }
252	
253	            if ( _currentId >= 0 && ( _topId > _currentId || _topId + maxItems <= _currentId ) ) { // out of view
254	                if ( _topId > _currentId ) { // scroll up, put current id on top
255	                    _topId = _currentId;
256	                }
257	                else if ( _topId + maxItems <= _currentId ) { // scroll down, put current id at bottom
258	                    _topId = _currentId + 1 - maxItems;
259	                }
260	            }
261	
262	            UpdateScrollbarRange();
263	            _scrollbar.moveToIndex( _topId );
264	        }
