266	        // Move visible area to the position with given element ID being on the top of the list.
267	        void setTopVisibleItem( const int topId )
268	        {
269	            Verify();
270	
271	            if ( !IsValid() ) {
272	                Reset();
273	                return;
274	            }
275	
276	            _topId = std::max( 0, std::min( topId, _size() - maxItems ) );
277	
278	            UpdateScrollbarRange();
279	            _scrollbar.moveToIndex( _topId );
280	        }
