282	        void SetCurrent( const Item & item )
283	        {
284	            typename std::vector<Item>::iterator pos = std::find( content->begin(), content->end(), item );
285	            if ( pos == content->end() )
286	                Reset();
287	            else
288	                _currentId = static_cast<int>( pos - content->begin() );
289	
290	            SetCurrentVisible();
291	        }
