300	        {
301	            return IsValid() && _currentId >= 0;
302	        }
303	
304	        void Unselect( void )
305	        {
306	            Verify();
307	            if ( IsValid() )
308	                _currentId = -1;
309	        }
310	
311	        bool QueueEventProcessing( void ) override
312	        {
313	            LocalEvent & le = LocalEvent::Get();
314	
315	            le.MousePressLeft( buttonPgUp.area() ) ? buttonPgUp.drawOnPress() : buttonPgUp.drawOnRelease();
316	            le.MousePressLeft( buttonPgDn.area() ) ? buttonPgDn.drawOnPress() : buttonPgDn.drawOnRelease();
317	
318	            if ( !IsValid() )
319	                return false;
320	
321	            if ( useHotkeys && le.KeyPress( KEY_PAGEUP ) && ( _topId > 0 ) ) {
322	                needRedraw = true;
323	
324	                if ( _topId > maxItems )
325	                    _topId -= maxItems;
326	                else
327	                    _topId = 0;
328	
329	                UpdateScrollbarRange();
330	                _scrollbar.moveToIndex( _topId );
331	
332	                return true;
333	            }
334	            else if ( useHotkeys && le.KeyPress( KEY_PAGEDOWN ) && ( _topId + maxItems < _size() ) ) {
335	                needRedraw = true;
336	
337	                _topId += maxItems;
338	                if ( _topId + maxItems >= _size() )
339	                    _topId = _size() - maxItems;
340	
341	                UpdateScrollbarRange();
342	                _scrollbar.moveToIndex( _topId );
343	
344	                return true;
345	            }
346	            else if ( useHotkeys && le.KeyPress( KEY_UP ) && ( _currentId > 0 ) ) {
347	                needRedraw = true;
348	
349	                --_currentId;
350	                SetCurrentVisible();
351	                ActionCurrentUp();
352	
353	                return true;
354	            }
355	            else if ( useHotkeys && le.KeyPress( KEY_DOWN ) && ( _currentId + 1 < _size() ) ) {
356	                needRedraw = true;
357	
358	                ++_currentId;
359	                SetCurrentVisible();
360	                ActionCurrentDn();
361	
362	                return true;
363	            }
364	            else if ( ( le.MouseClickLeft( buttonPgUp.area() ) || le.MouseWheelUp( rtAreaItems ) || le.MouseWheelUp( _scrollbar.getArea() )
365	                        || _timedButtonPgUp.isDelayPassed() )
366	                      && ( _topId > 0 ) ) {
367	                needRedraw = true;
368	
369	                --_topId;
370	                _scrollbar.backward();
371	
372	                return true;
373	            }
374	            else if ( ( le.MouseClickLeft( buttonPgDn.area() ) || le.MouseWheelDn( rtAreaItems ) || le.MouseWheelDn( _scrollbar.getArea() )
375	                        || _timedButtonPgDn.isDelayPassed() )
376	                      && ( _topId + maxItems < _size() ) ) {
377	                needRedraw = true;
378	
379	                ++_topId;
380	                _scrollbar.forward();
381	
382	                return true;
383	            }
384	            else if ( le.MousePressLeft( _scrollbar.getArea() ) && ( _size() > maxItems ) ) {
385	                needRedraw = true;
386	
387	                UpdateScrollbarRange();
388	
389	                const fheroes2::Point & mousePos = le.GetMouseCursor();
390	                _scrollbar.moveToPos( mousePos );
391	                _topId = _scrollbar.currentIndex();
392	
393	                _updateScrollbar = true;
394	
395	                return true;
396	            }
397	
398	            if ( _updateScrollbar ) {
399	                _updateScrollbar = false;
400	                if ( _scrollbar.updatePosition() ) {
401	                    needRedraw = true;
402	                    return true;
403	                }
404	            }
405	
406	            const fheroes2::Point & mousePos = le.GetMouseCursor();
407	            if ( rtAreaItems & mousePos ) { // within our rectangle
408	                needRedraw = true;
409	
410	                const int id = ( mousePos.y - rtAreaItems.y ) * maxItems / rtAreaItems.height + _topId;
411	
412	                if ( id < _size() ) {
413	                    Item & item = ( *content )[static_cast<size_t>( id )]; // id is always >= 0
414	                    const int32_t offsetY = ( id - _topId ) * rtAreaItems.height / maxItems;
415	
416	                    if ( ActionListCursor( item, mousePos ) )
417	                        return true;
418	
419	                    if ( le.MouseClickLeft( rtAreaItems ) ) {
420	                        if ( id == _currentId ) {
421	                            ActionListDoubleClick( item, mousePos, rtAreaItems.x, rtAreaItems.y + offsetY );
422	                        }
423	                        else {
424	                            _currentId = id;
425	                            ActionListSingleClick( item, mousePos, rtAreaItems.x, rtAreaItems.y + offsetY );
426	                        }
427	                        return true;
428	                    }
429	                    else if ( le.MousePressRight( rtAreaItems ) ) {
430	                        ActionListPressRight( item, mousePos, rtAreaItems.x, rtAreaItems.y + offsetY );
431	                        return true;
432	                    }
433	                }
434	
435	                needRedraw = false;
436	            }
437	
438	            return false;
439	        }
440	
441	    protected:
442	        bool needRedraw;
443	
444	        fheroes2::Rect rtAreaItems;
445	
446	        fheroes2::Button buttonPgUp;
447	        fheroes2::Button buttonPgDn;
448	
449	        fheroes2::Scrollbar _scrollbar;
450	
