456	    private:
457	        std::vector<Item> * content;
458	        int maxItems;
459	
460	        fheroes2::Point ptRedraw;
461	
462	        bool useHotkeys;
463	
464	        bool _updateScrollbar;
465	
466	        fheroes2::TimedEventValidator _timedButtonPgUp;
467	        fheroes2::TimedEventValidator _timedButtonPgDn;
468	
469	        void Verify()
470	        {
471	            if ( content == nullptr || content->empty() ) {
472	                _currentId = -1;
473	                _topId = -1;
474	            }
475	            else {
476	                if ( _currentId >= _size() )
477	                    _currentId = -1;
478	                if ( _topId < 0 || _topId >= _size() )
479	                    _topId = 0;
480	            }
481	        }
482	
483	        int _size() const
484	        {
485	            return content == nullptr ? 0 : static_cast<int>( content->size() );
486	        }
487	
488	        void UpdateScrollbarRange()
489	        {
490	            const int maxValue = ( content != nullptr && maxItems < _size() ) ? static_cast<int>( _size() - maxItems ) : 0;
491	            if ( _scrollbar.maxIndex() != maxValue )
492	                _scrollbar.setRange( 0, maxValue );
493	        }
